command:
$ErrorActionPreference = "Stop"
git fetch origin main work/search-v2 --no-tags
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git status --short).Count -ne 0) { throw "dirty checkout" }
if ((git rev-parse origin/main).Trim() -ne "ecca3e98000dad764f846be0d6483775b2610fe0") { throw "main moved" }
git checkout work/search-v2
if ($LASTEXITCODE -ne 0) { throw "checkout failed" }
git merge --ff-only origin/work/search-v2
if ($LASTEXITCODE -ne 0) { throw "branch update failed" }

$env:PYTHONPATH = "C:\dev\flyExplorer\tests\winui"
Write-Host "SEARCH_V2_SOURCE"
python -X utf8 -m unittest tests.winui.test_search_controller_contract tests.winui.test_search_v2_contract tests.winui.test_m19_contract
if ($LASTEXITCODE -ne 0) { throw "Search v2 source contracts failed" }

if (-not (Test-Path "out\winui\Release\flyExplorer.exe")) { throw "validated Release binary missing" }
$env:FLY_MIGRATION_CONFIGURATION = "Release"
$env:FLY_M19_OWNED_FEATURES = "YES"
Write-Host "ESTABLISHED_M19_GUI"
python -X utf8 -u tests\winui\test_shell_gui.py
if ($LASTEXITCODE -ne 0) { throw "established M19 GUI failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "SEARCH_V2_ESTABLISHED_GUI_PASS"
